{
    name: "paperclip_get_comments",
    description: "Read the comment thread of an issue (most recent first). Use this to get task context, instructions, and feedback before deciding you lack information.",
    parameters: {
        type: "object",
        properties: {
            issueId: { type: "string" },
            limit: { type: "number", description: "Max comments to return, default 10" },
        },
        required: ["issueId"],
    },
    run: async (args) => {
        const r = await call("GET", `/api/issues/${args.issueId}/comments`);
        if (!r.ok)
            return r;
        const items = Array.isArray(r.result) ? r.result : [];
        const limit = typeof args.limit === "number" && args.limit > 0 ? args.limit : 10;
        return {
            ok: true,
            comments: items.slice(0, limit).map((c) => ({
                id: c.id,
                author: c.authorAgentId ?? c.authorUserId ?? null,
                createdAt: c.createdAt,
                body: typeof c.body === "string" ? c.body.slice(0, 2000) : "",
            })),
        };
    },
},
{
    name: "paperclip_list_agents",
